/*
  Bathroom Music Controller — ESP32-WROOM-32
  ---------------------------------------------------------
  Features:
    - Light sensor on GPIO34 controls automatic playback
    - DFPlayer Mini on UART2 (ESP32 RX=GPIO16, TX=GPIO17)
    - Local Wi-Fi access point + web controller at http://192.168.4.1
    - Track selection, volume, automatic/manual mode
    - No cloud account or phone app required

  Required Arduino libraries:
    - DFRobotDFPlayerMini by DFRobot

  Wiring:
    LDR module S  -> GPIO34
    LDR module +  -> 3V3
    LDR module -  -> GND

    DFPlayer VCC   -> 5V (check your module's markings)
    DFPlayer GND   -> ESP32 GND
    DFPlayer TX    -> ESP32 GPIO16 (RX2)
    ESP32 GPIO17   -> 1k resistor -> DFPlayer RX
    DFPlayer DAC_L -> powered speaker line-in left
    DFPlayer DAC_R -> powered speaker line-in right
    DFPlayer GND   -> powered speaker line-in ground

  Put MP3 files in the root of a FAT32 microSD card as:
    001.mp3, 002.mp3, 003.mp3, ...
  Keep the electronics and power supply away from water and steam.
*/

#include <WiFi.h>
#include <WebServer.h>
#include <DFRobotDFPlayerMini.h>

const int LDR_PIN = 34;
const int DFPLAYER_RX_PIN = 16;  // ESP32 receives from DFPlayer TX
const int DFPLAYER_TX_PIN = 17;  // ESP32 transmits to DFPlayer RX

// Tune these after checking the real light sensor readings.
// If the sensor reading rises when the bathroom light turns on,
// use a threshold between the dark and bright readings.
int lightThreshold = 1800;
int lightHysteresis = 180;

const char* AP_SSID = "BathroomMusic";
const char* AP_PASSWORD = "Music1234";  // Change this if you wish.

WebServer server(80);
HardwareSerial dfSerial(2);
DFRobotDFPlayerMini player;

bool playerReady = false;
bool autoMode = true;
bool musicPlaying = false;
bool lightIsOn = false;
int currentTrack = 1;
int volumeLevel = 20;  // DFPlayer range: 0-30
unsigned long lastSensorRead = 0;
int lastLdrValue = 0;

String pageHtml() {
  String html = R"HTML(
<!doctype html>
<html>
<head>
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bathroom Music</title>
<style>
body{font-family:Arial,sans-serif;max-width:560px;margin:24px auto;padding:0 16px;background:#f4f1eb;color:#242424}
h1{margin-bottom:4px} .sub{color:#666;margin-top:0}
.card{background:white;border-radius:16px;padding:18px;margin:14px 0;box-shadow:0 2px 10px #0001}
button{border:0;border-radius:10px;padding:12px 15px;margin:4px;background:#333;color:white;font-size:16px}
button.secondary{background:#e5e2dc;color:#222}
input[type=range]{width:100%}
.row{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.small{font-size:14px;color:#555}
</style>
</head>
<body>
<h1>Bathroom Music 🎵</h1>
<p class="sub">Local controller · no internet required</p>
<div class="card">
  <h2>Status</h2>
  <p id="status">Loading…</p>
  <p class="small" id="sensor"></p>
  <div class="row">
    <button onclick="cmd('/play')">Play</button>
    <button onclick="cmd('/pause')">Pause</button>
    <button class="secondary" onclick="cmd('/stop')">Stop</button>
  </div>
</div>
<div class="card">
  <h2>Mode</h2>
  <p>Automatic mode starts music when the light is detected.</p>
  <div class="row">
    <button onclick="cmd('/mode?auto=1')">Automatic</button>
    <button class="secondary" onclick="cmd('/mode?auto=0')">Manual</button>
  </div>
</div>
<div class="card">
  <h2>Track</h2>
  <div class="row">
    <button class="secondary" onclick="cmd('/track?num=1')">1</button>
    <button class="secondary" onclick="cmd('/track?num=2')">2</button>
    <button class="secondary" onclick="cmd('/track?num=3')">3</button>
    <button class="secondary" onclick="cmd('/track?num=4')">4</button>
    <button class="secondary" onclick="cmd('/track?num=5')">5</button>
    <button class="secondary" onclick="cmd('/track?num=6')">6</button>
    <button class="secondary" onclick="cmd('/track?num=7')">7</button>
    <button class="secondary" onclick="cmd('/track?num=8')">8</button>
    <button class="secondary" onclick="cmd('/track?num=9')">9</button>
    <button class="secondary" onclick="cmd('/track?num=10')">10</button>
  </div>
  <p class="small">Files should be named 001.mp3, 002.mp3, etc. in the SD card root.</p>
</div>
<div class="card">
  <h2>Volume: <span id="volLabel">20</span>/30</h2>
  <input id="vol" type="range" min="0" max="30" value="20"
         oninput="volLabel.textContent=this.value"
         onchange="cmd('/volume?value='+this.value)">
  <h2>Light threshold: <span id="thresholdLabel">1800</span></h2>
  <input id="threshold" type="range" min="0" max="4095" value="1800"
         oninput="thresholdLabel.textContent=this.value"
         onchange="cmd('/threshold?value='+this.value)">
  <p class="small">Adjust the threshold so the reading when the light is on is above it, and the reading when off is below it (if your sensor behaves the other way around, ask to change the logic).</p>
</div>
<script>
async function cmd(path){try{await fetch(path);await update()}catch(e){document.getElementById('status').textContent='Could not reach ESP32';}}
async function update(){
 try{
  const r=await fetch('/status'); const s=await r.json();
  document.getElementById('status').textContent=
    (s.playerReady?'DFPlayer connected':'DFPlayer not detected')+' · '+
    (s.autoMode?'Automatic':'Manual')+' · '+(s.playing?'Playing':'Stopped')+
    ' · Track '+s.track;
  document.getElementById('sensor').textContent='Light sensor: '+s.ldr+' · Light detected: '+(s.lightOn?'Yes':'No');
  document.getElementById('vol').value=s.volume;
  document.getElementById('volLabel').textContent=s.volume;
  document.getElementById('threshold').value=s.threshold;
  document.getElementById('thresholdLabel').textContent=s.threshold;
 }catch(e){}
}
setInterval(update,2000); update();
</script>
</body>
</html>
)HTML";
  return html;
}

void startTrack(int trackNumber) {
  if (trackNumber < 1) trackNumber = 1;
  if (trackNumber > 999) trackNumber = 999;
  currentTrack = trackNumber;
  if (playerReady) {
    player.volume(volumeLevel);
    player.play(currentTrack);
    musicPlaying = true;
  }
}

void stopMusic() {
  if (playerReady) player.stop();
  musicPlaying = false;
}

void sendStatus() {
  String json = "{";
  json += "\"playerReady\":" + String(playerReady ? "true" : "false") + ",";
  json += "\"autoMode\":" + String(autoMode ? "true" : "false") + ",";
  json += "\"playing\":" + String(musicPlaying ? "true" : "false") + ",";
  json += "\"lightOn\":" + String(lightIsOn ? "true" : "false") + ",";
  json += "\"track\":" + String(currentTrack) + ",";
  json += "\"volume\":" + String(volumeLevel) + ",";
  json += "\"threshold\":" + String(lightThreshold) + ",";
  json += "\"ldr\":" + String(lastLdrValue);
  json += "}";
  server.send(200, "application/json", json);
}

void setupRoutes() {
  server.on("/", HTTP_GET, []() {
    server.send(200, "text/html", pageHtml());
  });

  server.on("/status", HTTP_GET, []() {
    sendStatus();
  });

  server.on("/play", HTTP_GET, []() {
    if (playerReady) {
      player.volume(volumeLevel);
      player.play(currentTrack);
      musicPlaying = true;
    }
    server.send(200, "text/plain", "OK");
  });

  server.on("/pause", HTTP_GET, []() {
    if (playerReady) player.pause();
    musicPlaying = false;
    server.send(200, "text/plain", "OK");
  });

  server.on("/stop", HTTP_GET, []() {
    stopMusic();
    server.send(200, "text/plain", "OK");
  });

  server.on("/track", HTTP_GET, []() {
    if (server.hasArg("num")) startTrack(server.arg("num").toInt());
    server.send(200, "text/plain", "OK");
  });

  server.on("/volume", HTTP_GET, []() {
    if (server.hasArg("value")) {
      volumeLevel = constrain(server.arg("value").toInt(), 0, 30);
      if (playerReady) player.volume(volumeLevel);
    }
    server.send(200, "text/plain", "OK");
  });

  server.on("/threshold", HTTP_GET, []() {
    if (server.hasArg("value")) lightThreshold = constrain(server.arg("value").toInt(), 0, 4095);
    server.send(200, "text/plain", "OK");
  });

  server.on("/mode", HTTP_GET, []() {
    if (server.hasArg("auto")) autoMode = server.arg("auto").toInt() != 0;
    if (!autoMode) {
      // Switching to manual mode leaves playback under user control.
    } else if (lightIsOn && !musicPlaying) {
      startTrack(currentTrack);
    } else if (!lightIsOn && musicPlaying) {
      stopMusic();
    }
    server.send(200, "text/plain", "OK");
  });

  server.begin();
}

void setup() {
  Serial.begin(115200);
  delay(500);
  Serial.println();
  Serial.println("Bathroom Music Controller starting...");

  analogReadResolution(12);
  analogSetPinAttenuation(LDR_PIN, ADC_11db);
  pinMode(LDR_PIN, INPUT);

  dfSerial.begin(9600, SERIAL_8N1, DFPLAYER_RX_PIN, DFPLAYER_TX_PIN);
  delay(300);
  if (player.begin(dfSerial, true, true)) {
    playerReady = true;
    player.volume(volumeLevel);
    player.EQ(DFPLAYER_EQ_NORMAL);
    Serial.println("DFPlayer detected.");
  } else {
    playerReady = false;
    Serial.println("DFPlayer not detected. Web controller will still work.");
  }

  WiFi.mode(WIFI_AP);
  bool apStarted = WiFi.softAP(AP_SSID, AP_PASSWORD);
  Serial.print("Wi-Fi access point: ");
  Serial.println(apStarted ? "started" : "FAILED");
  Serial.print("Connect to Wi-Fi: ");
  Serial.println(AP_SSID);
  Serial.print("Then open: http://");
  Serial.println(WiFi.softAPIP());

  setupRoutes();
  Serial.println("Bathroom Music Controller ready.");
}

void loop() {
  server.handleClient();

  if (millis() - lastSensorRead >= 200) {
    lastSensorRead = millis();
    lastLdrValue = analogRead(LDR_PIN);

    // Hysteresis avoids rapid switching around the threshold.
    if (!lightIsOn && lastLdrValue > lightThreshold + lightHysteresis) {
      lightIsOn = true;
    } else if (lightIsOn && lastLdrValue < lightThreshold - lightHysteresis) {
      lightIsOn = false;
    }

    if (autoMode) {
      if (lightIsOn && !musicPlaying) {
        startTrack(currentTrack);
      } else if (!lightIsOn && musicPlaying) {
        stopMusic();
      }
    }
  }
}
